sp_widget.client_script:
api.controller = function($scope, $window) {
    var c = this;

    // Mobile menu
    c.menuOpen = false;
    c.toggleMenu = function() {
        c.menuOpen = !c.menuOpen;
    };

    if (typeof g_user !== 'undefined' && g_user.hasRole('x_2206701_hotel_0.registered_user') &&
        !g_user.hasRole('x_2206701_hotel_0.receptionist') &&
        !g_user.hasRole('x_2206701_hotel_0.administrator') &&
        !g_user.hasRole('x_2206701_hotel_0.manager')) {
        var currentPath = $window.location.pathname;
        if (currentPath === '/' || currentPath.indexOf('/navpage.do') > -1 || currentPath.indexOf('/login.do') > -1) {
            $window.location.href = '/hotel?id=hotel_reservation_home_page';
        }
    }
};

sp_widget.css:
.ch-header {
  position: sticky;
  top: 0;
  z-index: 50;
  width: 100%;
  background: rgba(250, 246, 239, .94);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid #e7e1d4;
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Arial, sans-serif;
  font-size: 15px;
  line-height: 1.6;
}
.ch-header, .ch-header * { box-sizing: border-box; }
.ch-header a, .ch-header a:hover, .ch-header a:focus { text-decoration: none; }

.ch-container { width: 92%; max-width: 1120px; margin: 0 auto; }
.ch-nav { display: flex; align-items: center; justify-content: space-between; height: 76px; position: relative; }

/* Logo */
.ch-logo { display: flex; align-items: center; flex-shrink: 0; }
.ch-logo img { height: 50px; width: auto; display: block; }

/* Links */
.ch-links { display: flex; gap: 30px; align-items: center; }
.ch-links a:not(.ch-btn) {
  font-size: .75rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  font-weight: 500;
  color: #2a2d29;
  padding: 6px 0;
  border-bottom: 2px solid transparent;
  transition: .2s;
  white-space: nowrap;
}
.ch-links a:not(.ch-btn):hover,
.ch-links a.active { border-color: #d4b07c; color: #1f3a30; }

/* Logged-in user */
.ch-user { display: flex; align-items: center; gap: 8px; max-width: 190px; }
.ch-avatar {
  width: 28px; height: 28px; flex-shrink: 0; border-radius: 50%;
  background: #1f3a30; color: #e6c79c;
  display: grid; place-items: center;
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 1rem; font-weight: 700; text-transform: uppercase;
}
.ch-user-name {
  font-size: .8rem; font-weight: 600; color: #1f3a30;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

/* Book Now button */
.ch-header a.ch-btn {
  display: inline-block;
  padding: 9px 18px;
  border-radius: 6px;
  background: #1f3a30;
  color: #ffffff;
  font-size: .7rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  font-weight: 600;
  border: 1px solid transparent;
  transition: .25s ease;
  white-space: nowrap;
}
.ch-header a.ch-btn:hover { background: #162a22; color: #ffffff; transform: translateY(-2px); box-shadow: 0 10px 30px rgba(31, 58, 48, .08); }

/* Mobile toggle (hidden on desktop) */
.ch-toggle {
  display: none;
  background: none;
  border: 1px solid #e7e1d4;
  border-radius: 6px;
  font-size: 1.3rem;
  width: 42px; height: 42px;
  color: #1f3a30;
  cursor: pointer;
}

@media (max-width: 900px) {
  .ch-toggle { display: block; }
  .ch-links {
    display: none;
    position: absolute;
    top: 100%; left: -4%; right: -4%;
    background: #faf6ef;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    padding: 8px 4% 20px;
    border-bottom: 1px solid #e7e1d4;
    box-shadow: 0 10px 30px rgba(31, 58, 48, .08);
  }
  .ch-links.open { display: flex; }
  .ch-links a:not(.ch-btn) { padding: 14px 0; border-bottom: 1px solid #e7e1d4; }
  .ch-user { max-width: none; padding: 14px 0; border-bottom: 1px solid #e7e1d4; }
  .ch-header a.ch-btn { margin-top: 14px; text-align: center; }
}

sp_widget.script:
(function() {
    data.isLoggedIn = gs.isLoggedIn();
    data.userName = gs.isLoggedIn() ? gs.getUserDisplayName() : '';

    data.pages = {
        home: 'hotel_reservation_home_page',
        rooms: 'hotel_rooms',
        reservations: 'my_reservations',
        lookup: 'guest_lookup',
        login: 'login',
        activities: 'book_sports',
        book: 'book_room'
    };

    data.page = $sp.getParameter('id') || data.pages.home;
})();
